pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Owner is the default msg.sender of setUp, so we use that address
        address owner = address(this);
        // Fund owner with 1 wei
        vm.deal(owner, 1 wei);

        // Owner calls sendMoney(owner, 1 wei) — sends 1 wei to itself
        // In reference: transfer reverts because receive() increments depositsCount (reentrancy not allowed), so sendMoney reverts
        // In mutant: call{value:1 wei} succeeds, receive() runs, depositsCount becomes 1

        // First, set depositsCount to 0 (already default)
        uint initialCount = c.depositsCount();

        // Try the call
        vm.prank(owner);
        try c.sendMoney(owner, 1 wei) {
            // If it succeeds, check depositsCount
            assertTrue(c.depositsCount() == 1, "mutant: call succeeded, count incremented");
        } catch {
            // If it reverts, check depositsCount unchanged
            assertTrue(c.depositsCount() == 0, "reference: transfer reverted, count unchanged");
        }
    }
}

